// Playwright config generated by reverse-qa. Projects:
//   unit      pure helpers, no browser and no app (RQA_SKIP_SETUP=1)
//   selftest  the framework's own fixtures against the running app (database, snapshots, PHP log, outbound guard)
//   chromium  every tier except visual (the default)
//   firefox, webkit, mobile   smoke, flows and journeys on other engines and a phone viewport
//   visual    screenshot comparison, Chromium only (run it in the official Playwright Docker image in CI)
//   crawl     not a test tier: crawl-app walks the app as every role and writes output/scan/crawl.json
// A desktop app (target.yaml app.driver: electron) has one test project, `desktop`: its tests start the app itself
// and no browser, so there is nothing to repeat on other engines.
// Reports (named by RQA_REPORT): test-results/<name>.json for coverage, RTM, triage and Xray;
// test-results/<name>-junit.xml for Xray's JUnit import; playwright-report/ (HTML). run-suites names every step; its
// full tier is `report`, the file the reports read. A run started by hand names nothing and is called `adhoc`, so it
// can never replace that file.
import { defineConfig, devices } from '@playwright/test';
import { baseURL, isDesktop } from './support/target.ts';

// --list only names the tests. It must never overwrite a run's report: its "report" would show every test as not run.
const name = process.argv.includes('--list') ? 'list' : process.env.RQA_REPORT ?? 'adhoc';
const crossBrowser = /@smoke|@flow|@e2e/;

export default defineConfig({
  testDir: './tests',
  outputDir: `./test-results/${name}-artifacts`, // one folder per run name, so UI mode and run-suites never collide
  timeout: 30_000,
  expect: { timeout: 5_000 },
  fullyParallel: false,
  workers: Number(process.env.WORKERS ?? 1), // tests share one database; raise only for read-only tiers
  retries: Number(process.env.RETRIES ?? 0), // flakiness is caught by the flake gate (--repeat-each=5), not hidden by retries
  forbidOnly: Boolean(process.env.CI),
  globalSetup: './support/global-setup.ts',
  globalTeardown: './support/global-teardown.ts', // records, then removes, the test data the run created
  reporter: [
    ['list'],
    ['html', { open: 'never', outputFolder: 'playwright-report' }],
    ['json', { outputFile: `test-results/${name}.json` }],
    ['@xray-app/playwright-junit-reporter', { outputFile: `test-results/${name}-junit.xml`, embedAnnotationsAsProperties: true, textContentAnnotations: ['test_description'], embedAttachmentsAsProperty: 'testrun_evidence' }],
  ],
  use: {
    baseURL,
    trace: 'retain-on-failure',
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
    launchOptions: { slowMo: Number(process.env.SLOWMO ?? 0) },
  },
  projects: isDesktop ? [
    { name: 'unit', testDir: './unit', testMatch: '**/*.unit.ts' },
    { name: 'selftest', testDir: './selftest', testMatch: '**/*.selftest.ts' },
    { name: 'desktop' }, // every tier the desktop driver has; each test starts the app itself (about 6-8 s a start)
    { name: 'crawl', testDir: './crawl' },
  ] : [
    { name: 'unit', testDir: './unit', testMatch: '**/*.unit.ts' },
    { name: 'selftest', testDir: './selftest', testMatch: '**/*.selftest.ts' },
    { name: 'chromium', use: { ...devices['Desktop Chrome'] }, testIgnore: ['**/visual/**'] },
    { name: 'firefox', use: { ...devices['Desktop Firefox'] }, grep: crossBrowser, testIgnore: ['**/visual/**'] },
    { name: 'webkit', use: { ...devices['Desktop Safari'] }, grep: crossBrowser, testIgnore: ['**/visual/**'] },
    { name: 'mobile', use: { ...devices['Pixel 7'] }, grep: /@smoke|@e2e/, testIgnore: ['**/visual/**'] },
    { name: 'visual', use: { ...devices['Desktop Chrome'] }, testMatch: '**/visual/**' },
    { name: 'crawl', testDir: './crawl', use: { ...devices['Desktop Chrome'] } }, // crawl-app: records what each role can reach
  ],
});
